import{_ as d,o as t,c as a,a2 as o}from"./chunks/framework.D7EuCHIT.js";const y=JSON.parse('{"title":"宿主组件与平台适配","description":"","frontmatter":{},"headers":[],"relativePath":"developers/components.md","filePath":"developers/components.md","lastUpdated":1795341627000}'),r={name:"developers/components.md"};function c(s,e,i,l,n,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="宿主组件与平台适配" tabindex="-1">宿主组件与平台适配 <a class="header-anchor" href="#宿主组件与平台适配" aria-label="Permalink to &quot;宿主组件与平台适配&quot;">​</a></h1><p>此页按界面区域列出宿主现有的公开配置和扩展入口。参数类型、默认值和约束以<a href="/LyraPlayer-docs-site/config/reference/">配置参考</a>为准。</p><table tabindex="0"><thead><tr><th>组件或区域</th><th>配置表</th><th>公开行为或扩展</th></tr></thead><tbody><tr><td>外壳、抽屉和卡片布局</td><td><code>shell</code>、<code>geometry</code></td><td><a href="/LyraPlayer-docs-site/plugins/navigation">导航扩展</a></td></tr><tr><td>底部播放条</td><td><code>dock</code>、<code>theme</code></td><td><a href="/LyraPlayer-docs-site/plugins/playback">播放接口</a></td></tr><tr><td>播放页、封面和流动背景</td><td><code>player</code>、<code>cover_fx</code>、<code>flow</code></td><td><a href="/LyraPlayer-docs-site/plugins/styles">样式与绘制</a></td></tr><tr><td>歌词</td><td><code>player</code> 的 <code>lyric_*</code> 参数</td><td>歌词资源与播放进度由宿主管理</td></tr><tr><td>展开面板</td><td><code>sheet</code>、<code>scroll</code></td><td><a href="/LyraPlayer-docs-site/plugins/styles">Scene 绘制协议</a></td></tr><tr><td>资料库和搜索</td><td><code>search</code>、<code>profile</code>、<code>scroll</code></td><td><a href="/LyraPlayer-docs-site/plugins/media">媒体资源</a>、<a href="/LyraPlayer-docs-site/plugins/personal-library">私人资料库</a></td></tr><tr><td>设置页</td><td><code>settings</code>、<code>theme</code></td><td><a href="/LyraPlayer-docs-site/plugins/settings-page">声明式设置页协议</a></td></tr><tr><td>样式选择器</td><td><code>style</code></td><td>宿主提供 Bloom、Ember 和沉浸样式。插件可以向同一选择器提供样式描述</td></tr></tbody></table><h2 id="配置与应用样式" tabindex="-1">配置与应用样式 <a class="header-anchor" href="#配置与应用样式" aria-label="Permalink to &quot;配置与应用样式&quot;">​</a></h2><ul><li>改全局配色用 <code>theme</code>。改尺寸和间距用对应区域的表。配置读写遵循<a href="/LyraPlayer-docs-site/plugins/config-schema">配置接口和字段约束</a>。</li><li>播放页整体样式用<a href="/LyraPlayer-docs-site/plugins/styles">样式与绘制接口</a>。需要自绘时通过 Scene 提交画面。</li><li>声明式设置行由宿主绘制。插件接收激活或确认消息，并处理校验、持久化和失败反馈。行标记、禁用状态、当前值和可用操作见<a href="/LyraPlayer-docs-site/plugins/settings-page">设置页协议</a>。</li></ul><h2 id="android-布局和能力" tabindex="-1">Android 布局和能力 <a class="header-anchor" href="#android-布局和能力" aria-label="Permalink to &quot;Android 布局和能力&quot;">​</a></h2><p>宿主从 Android 8（API 26）起支持，正式插件应提供 <code>arm64-v8a</code> 构建。插件使用公开帧和布局数据适配当前窗口尺寸及安全区。横屏、竖屏和有系统栏遮挡的窗口都应使用实际可用空间做绘制和命中。尺寸单位查对应配置键的定义，绘制坐标查 Scene 协议。</p><p>调用 Android 能力时，遵循<a href="/LyraPlayer-docs-site/plugins/android">Android 平台契约</a>的线程、引用和权限要求。能力可用性按运行设备版本及宿主声明判断。</p><h2 id="像素、密度和字体缩放" tabindex="-1">像素、密度和字体缩放 <a class="header-anchor" href="#像素、密度和字体缩放" aria-label="Permalink to &quot;像素、密度和字体缩放&quot;">​</a></h2><p>通过 <code>LYRA_INTERFACE_PRESENTATION_CONTEXT</code>（17）在帧线程读取 <code>LyraPresentationSnapshotV3</code>。调用 <code>snapshot</code> 前将 <code>size</code> 设为 <code>sizeof(snapshot)</code>，并检查返回值。整卡片样式的绘制回调优先使用本次回调收到的卡片矩形，选择器预览时这个矩形可能比主卡片小。</p><table tabindex="0"><thead><tr><th>输入</th><th>使用方式</th></tr></thead><tbody><tr><td><code>width</code>、<code>height</code> 与 <code>card</code>、<code>cover</code>、<code>library</code> 等矩形</td><td>使用当前窗口的像素坐标。自绘和触摸命中共用同一矩形</td></tr><tr><td>配置键定义为 dp</td><td>乘以当前 <code>density</code> 后用于像素布局</td></tr><tr><td>配置键定义为 sp</td><td>乘以当前 <code>density</code> 和 <code>font_scale</code> 后用于文字布局</td></tr><tr><td>安全区</td><td>宿主默认组件已处理自身布局。扩展叠加内容可以使用宿主提供的区域矩形。完全自绘的根若需要原始系统栏或挖孔内边距，可通过当前 Android Activity 查询系统能力</td></tr></tbody></table><p>窗口旋转、大小变化或系统字体缩放改变后，按新的帧数据计算绘制与命中。缓存文字布局时，把实际文字宽度和换算后的字号纳入缓存条件。Android 进程、线程和权限的约束适用于完全自绘的根和局部扩展。<a href="/LyraPlayer-docs-site/reference/abi">公开 SDK</a>、<a href="/LyraPlayer-docs-site/plugins/styles">样式与绘制</a>、<a href="/LyraPlayer-docs-site/plugins/android">Android 平台契约</a>。</p>',12)])])}const f=d(r,[["render",c]]);export{y as __pageData,f as default};
